/* Dragonfarm: Reborn — original browser implementation inspired by the 2002 game.
   No original copyrighted art, code or numerical balance data has been used. */
'use strict';
const APP_VERSION='0.7.2',SAVE_KEY='dragonfarm_reborn_save_v3';
const $=s=>document.querySelector(s);
const rnd=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
const clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n));
const fmt=n=>Math.round(n).toLocaleString('en-GB');
const money=n=>`${fmt(n)} gold`;
const safe=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SPECIES=[
{id:'ember',name:'Ember Wyrm',region:'Ashlands',color:'#dc7158',wing:'#aa453a',accent:'#ffc075',cost:530,feed:2,power:74,beauty:49,speed:53,grace:43,flight:true,about:'Fire-breathing, proud and dangerous in the arena.'},
{id:'verdant',name:'Mossback',region:'Greenwood',color:'#6b9e79',wing:'#3c725d',accent:'#cde0a3',cost:390,feed:2,power:57,beauty:70,speed:54,grace:74,flight:true,about:'Calm forest dragons with impressive scales and elegant movement.'},
{id:'tide',name:'Tide Serpent',region:'Marshes',color:'#6aa5c2',wing:'#4177a1',accent:'#a9e4e2',cost:430,feed:2,power:51,beauty:79,speed:77,grace:83,flight:true,about:'Quick, shimmering and renowned for the exhibition stage.'},
{id:'stone',name:'Ironhide',region:'Highlands',color:'#a59980',wing:'#676e60',accent:'#f0d39a',cost:620,feed:3,power:84,beauty:38,speed:35,grace:27,flight:false,about:'Armored mountain dragon with immense stamina.'},
{id:'dune',name:'Dune Runner',region:'Dunes',color:'#c49b69',wing:'#ae7350',accent:'#ffe0a1',cost:470,feed:2,power:61,beauty:67,speed:83,grace:77,flight:false,about:'Fast desert-born dragon, excellent at evading attacks.'},
{id:'royal',name:'Crown Dragon',region:'Volcano',color:'#af80bd',wing:'#70528e',accent:'#f7d3ff',cost:950,feed:4,power:87,beauty:92,speed:65,grace:66,flight:true,about:'Exceptionally rare sovereign of the volcanic peaks.'}
];
const FEEDS=[{id:'basic',name:'Ordinary feed',cost:10,desc:'Balanced everyday nutrition.'},{id:'power',name:'Power feed',cost:18,desc:'Strength and combat performance.'},{id:'beauty',name:'Lustre feed',cost:18,desc:'Glossy scales, grace and beauty.'},{id:'vital',name:'Vital blend',cost:24,desc:'Supports health and recovery.'}];
const BUILDINGS=[{id:'stable',name:'Dragon stable',icon:'🏚️',cost:450,months:1,max:6,desc:'One additional dragon slot.'},{id:'range',name:'Open enclosure',icon:'🌿',cost:350,months:1,max:1,desc:'Freedom and happiness; flying dragons can escape without a dome.'},{id:'dome',name:'Flight dome',icon:'🔮',cost:400,months:1,max:1,desc:'Protects flying dragons from escaping the enclosure.'},{id:'training',name:'Training center',icon:'⚔️',cost:680,months:2,max:1,desc:'Home training and safe practice sparring.'},{id:'breeding',name:'Breeding enclosure',icon:'🥚',cost:740,months:2,max:1,desc:'Pair adult dragons of the same species.'},{id:'hatchery',name:'Hatchery',icon:'🔥',cost:570,months:2,max:1,desc:'Incubates eggs more quickly; upgrade for two eggs.'},{id:'clinic',name:'Dragon clinic',icon:'✚',cost:590,months:2,max:1,desc:'Treat illness and wounds on your farm.'},{id:'tower',name:'Watchtower',icon:'♜',cost:410,months:1,max:4,desc:'Employ guards to resist sabotage.'}];
const RIVALS=[{name:'Galein Tuisdor',trait:'Gentle breeder',color:'#83b29b',focus:'beauty'},{name:'Todal Strendlun',trait:'Relentless fighter',color:'#cf786c',focus:'power'},{name:'Ansen Wokdal',trait:'Cautious merchant',color:'#d8b66f',focus:'wealth'},{name:'Soran Heimgral',trait:'Ruthless opportunist',color:'#a990ae',focus:'power'},{name:'Alendra Kirak',trait:'Master of spectacle',color:'#7fa5c8',focus:'beauty'}];
const QUESTS=[{id:'trainer',title:'The first champion',description:'Win a dragon fight.',predicate:s=>s.wins.fights>=1,reward:300,artifact:'Champion’s Claw',effect:'power'},{id:'keeper',title:'A flourishing nursery',description:'Own three living dragons.',predicate:s=>s.dragons.length>=3,reward:220,artifact:'Heart of the Grove',effect:'beauty'},{id:'builder',title:'A serious enterprise',description:'Build a training center and a breeding enclosure.',predicate:s=>s.buildings.training>0&&s.buildings.breeding>0,reward:400,artifact:'Ember Sigil',effect:'power'},{id:'performer',title:'A crowd favorite',description:'Win a beauty show.',predicate:s=>s.wins.shows>=1,reward:260,artifact:'Moonstone Pendant',effect:'beauty'}];
let state=null,view='island',modal=null,selected=null,shopTab='dragons',cartMode='food',battle=null,showGame=null,battleTimer=null,showTimer=null,toastTimer=null,fx='',newGameMode='normal',newDifficulty='normal';
let rosterOpen=false,moreOpen=false;
function species(id){return SPECIES.find(x=>x.id===id)||SPECIES[0]}
function initialRivals(){return RIVALS.map((r,i)=>({...r,gold:900+rnd(0,500),fights:0,shows:0,dragonPower:45+rnd(0,12)+(r.focus==='power'?9:0),dragonBeauty:48+rnd(0,15)+(r.focus==='beauty'?9:0),guards:rnd(0,2),angry:0}));}
function makeDragon(kind,age=9,parents=null){const s=species(kind);const heredity=(key,base)=>parents?clamp(Math.round((parents[0][key]+parents[1][key])/2+rnd(-8,8)),18,98):clamp(base+rnd(-15,14),15,98);
 const maxHealth=clamp(68+Math.round(heredity('power',s.power)/5)+rnd(-5,10),60,105);
 return {id:'d'+Date.now().toString(36)+Math.random().toString(36).slice(2,7),name:s.name.split(' ')[0]+'-'+rnd(100,999),kind,sex:Math.random()<.5?'female':'male',age,power:heredity('power',s.power),beauty:heredity('beauty',s.beauty),speed:heredity('speed',s.speed),grace:heredity('grace',s.grace),aggression:rnd(20,80),maxHealth,health:maxHealth,weight:45+Math.round(heredity('power',s.power)*.6),mood:80,nutrition:85,ration:s.feed,feed:'basic',trained:0,wins:0,shows:0,cooldown:0,injured:false,doped:0,artifact:null,appraised:false};}
function newGame(name='Keeper',mode='normal',difficulty='normal'){
 stopMiniGames();selected=null;modal=null;view='island';shopTab='dragons';
 state={version:APP_VERSION,name:String(name).slice(0,28)||'Keeper',mode,difficulty,month:1,limit:24,gold:2500,bank:0,bankRelease:0,interest:0,dragons:[],eggs:[],cargo:[],buildings:{stable:1,range:0,dome:0,training:0,breeding:0,hatchery:0,clinic:0,tower:0},construction:[],wagons:1,wagonLevel:0,food:{basic:8,power:0,beauty:0,vital:0},staff:{keepers:0,guards:0},hunt:null,offers:[],market:[],activeQuests:[],inventory:[],claimed:[],ledger:[],log:[],rivals:initialRivals(),wins:{fights:0,shows:0},monthFight:false,monthShow:false,totalEarned:2500,gameOver:false,progress:0,settings:{autoCombat:false,autoShow:false},tutorial:DragonTutorial.fresh()};
 refreshMarket();writeLog('Welcome to Alterica. Your stable is empty. Visit the city to buy your first dragon.');writeLog('Every turn is one month. Balance feeding, upkeep and tournament prizes.');save();render();toast('Your farm awaits, '+state.name+'.');
}
function hasSavedGame(){try{return !!localStorage.getItem(SAVE_KEY)}catch{return false}}
function load(){try{const s=JSON.parse(localStorage.getItem(SAVE_KEY));if(!s||!s.version||!s.dragons||!s.buildings||!s.rivals)return false;state=s;selected=s.dragons[0]?.id||null;view='island';return true}catch{return false}}
function save(){if(!state)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch{toast('Browser storage unavailable. Use Export Save.')}}
function writeLog(message){state.log.unshift({month:state.month,text:message});state.log=state.log.slice(0,110)}
function spend(amount,reason){if(state.gold<amount){toast(`Need ${money(amount-state.gold)} more.`);return false}state.gold-=amount;state.ledger.unshift({month:state.month,amount:-amount,reason});state.ledger=state.ledger.slice(0,160);return true}
function earn(amount,reason){state.gold+=amount;state.totalEarned+=amount;state.ledger.unshift({month:state.month,amount,reason});state.ledger=state.ledger.slice(0,160)}
function toast(m){const area=$('#toasts');if(!area)return;let p=document.createElement('div');p.className='toast';p.textContent=m;area.appendChild(p);setTimeout(()=>p.remove(),3700)}
function ownsBuilding(id){return (state.buildings[id]||0)>0}
function stableFree(){return state.buildings.stable-state.dragons.length-state.cargo.filter(x=>x.type==='dragon').length-state.eggs.length}
function assignedStableFree(){return state.buildings.stable-state.dragons.length-state.eggs.length}
function dBy(id){return state.dragons.find(d=>d.id===id)}
function myDragon(){return dBy(selected)||state.dragons[0]||null}
function basePrice(d){return species(d.kind).cost+Math.round((d.power+d.beauty+d.speed-180)*2.6)+d.wins*95+d.shows*75-Math.max(0,60-d.health)*2}
function wagonWeight(){return 95+state.wagonLevel*100}
function maxCargo(){return 12+state.wagonLevel*13}
function currentWagonItems(){return state.cargo.reduce((n,x)=>n+(x.type==='dragon'?12:x.count),0)}
function freeCargo(){return Math.max(0,state.wagons*maxCargo()-currentWagonItems())}
function canShip(d){return wagonWeight()>=d.weight}
function refreshMarket(){state.market=Array.from({length:4},(_,i)=>{const kind=SPECIES[(i+Math.floor((state.month-1)/2))%SPECIES.length].id;let d=makeDragon(kind,rnd(7,25));return {...d,price:Math.max(170,Math.round(basePrice(d)*(1+Math.random()*.18)))}})}
