function gameScore(s=state,who=null){if(who){if(s.mode==='combat')return who.fights;if(s.mode==='beauty')return who.shows;if(s.mode==='gold')return who.gold;return who.gold+who.dragonPower*12+who.dragonBeauty*7}
 if(s.mode==='combat')return s.wins.fights;if(s.mode==='beauty')return s.wins.shows;if(s.mode==='gold')return s.gold+s.bank;
 return s.gold+s.bank+s.dragons.reduce((t,d)=>t+Math.max(80,basePrice(d)),0)+Object.entries(s.buildings).reduce((t,[k,v])=>t+(BUILDINGS.find(b=>b.id===k)?.cost||0)*v*.6,0)}
function moveView(v){if(!state)return;if(battle||showGame)return;view=v;DragonTutorial.onView(state,v);save();render();}
